#!/usr/bin/env node
/* The platform deploys each function alone (functions/ is its source directory), so a shared library cannot be
   resolved at run time. This step puts the one module the subscribe action needs, `@krizaka/rate-limit/turnstile`
   (dependency-free, an ES module), next to it as `turnstile.mjs`, byte for byte under a generated header.
   `npm run functions:bundle` writes it; `--check` (the unit test) fails when the committed file drifted from the
   installed version. Never edit the generated file: bump the package and run the step. */
import { readFileSync, writeFileSync, existsSync } from "node:fs";

const SOURCE = new URL("../node_modules/@krizaka/rate-limit/dist/turnstile.js", import.meta.url);
const PACKAGE = new URL("../node_modules/@krizaka/rate-limit/package.json", import.meta.url);
export const TARGET = new URL("../functions/packages/newsletter/subscribe/turnstile.mjs", import.meta.url);

export function render() {
  const code = readFileSync(SOURCE, "utf8").replace(/\n\/\/# sourceMappingURL=.*\n?$/, "\n");
  if (/^\s*import[\s{]/m.test(code)) throw new Error("turnstile.js now imports something: a real bundler is needed");
  const { version } = JSON.parse(readFileSync(PACKAGE, "utf8"));
  return `// GENERATED by scripts/bundle-functions.mjs from @krizaka/rate-limit@${version} (turnstile). Do not edit.\n${code}`;
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  const out = render();
  if (process.argv.includes("--check")) {
    if (!existsSync(TARGET) || readFileSync(TARGET, "utf8") !== out) {
      console.error("functions/packages/newsletter/subscribe/turnstile.mjs is out of date: run `npm run functions:bundle`");
      process.exit(1);
    }
  } else {
    writeFileSync(TARGET, out);
    console.log("wrote", TARGET.pathname);
  }
}
